    pub const PREVIEW_STALE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/dids:previewStale",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vta/dids:stepUpRequired`
